// build checks the graph's inputs, then builds a root.
func (g *Graph) build(root string, force func()) error {
	var missing []string
	if g.Ctx == nil {
		missing = append(missing, "Ctx")
	}
	if g.Cfg == nil {
		missing = append(missing, "Cfg")
	}
	if g.Log == nil {
		missing = append(missing, "Log")
	}
	if len(missing) > 0 {
		return fmt.Errorf("build %s: set app.Graph's %s before building a root", root, strings.Join(missing, ", "))
	}
	// Construction is reported to the boot probes on Ctx (none when Ctx
	// carries none), so while a constructor blocks boot /readyz names it as
	// building, beside every node already built.
	if bp := serverkit.BootProbesFrom(g.Ctx); bp != nil {
		g.b.ReportTo(bp)
	}
	return g.b.Build(root, force)
}

// Built names every node Build constructed, each after its dependencies.
func (g *Graph) Built() []string { return g.b.Built() }

// BuildAPI constructs the api root — every node its fields
// reach, once, dependencies first — then seals the graph. Start order as
// compose.go wires it today (stop is the reverse):
//
//	api_settings → integration_settings → process_settings → db_repo → database → process_runtime → api_debug_server → payload_store → nats_conn → temporal_client → streaming_hub → user_update_hub → chat_update_hub → repo_update_feed → api_daemon_router → payload_gc → reliant_key_sweep → pause_service → reset_guard → chat → queued_deliverer → daemon_state_publisher → workflow_reconciler → vault → github_access → github_access_loop → project → daemon_events_consumer → queued_delivery → worktree_sweep → worktree_sweeper → trigger_pollers → schedule_syncer → trigger_schedule_sync → trigger_alerting → trigger_reconciler → trigger_redriver → tls_files → token_authority → user_auth → user_chain → account → approval → attachment → background → api_connections → connection → worktree → run → trigger_inbound → trigger_senders → input_options → trigger → api_tools_factory → api_catalog_search → catalog → connector_grants → connector → daemon → daemon_registry → file_system → forge → inbox → mcp → message → model_endpoint → package_commands → task → plan → preset → provider_account → question → repo → scenario → settings → streaming → system → terminal → token → tool_call → workflow → user_routes → http_routes → api_listener
func (g *Graph) BuildAPI() (*API, error) {
	if g.ApiServerConfig == nil {
		return nil, fmt.Errorf("build api: set app.Graph's ApiServerConfig before building the root: its closure reads it")
	}
	if g.DatabaseConfig == nil {
		return nil, fmt.Errorf("build api: set app.Graph's DatabaseConfig before building the root: its closure reads it")
	}
	if g.ServerProcessConfig == nil {
		return nil, fmt.Errorf("build api: set app.Graph's ServerProcessConfig before building the root: its closure reads it")
	}
	r := &API{}
	err := g.build("api", func() {
		// Last field first, so the first field starts last and stops first.
		r.APISettings = g.APISettings()
		r.Settings = g.ProcessSettings()
		r.Runtime = g.ProcessRuntime()
		r.Debug = g.APIDebugServer()
		r.Temporal = g.TemporalClient()
		r.Streaming = g.StreamingHub()
		r.Feed = g.RepoUpdateFeed()
		r.Router = g.APIDaemonRouter()
		r.PayloadGC = g.PayloadGC()
		r.KeySweep = g.ReliantKeySweep()
		r.Reconciler = g.WorkflowReconciler()
		r.GitHubAccess = g.GitHubAccessLoop()
		r.DaemonEvents = g.DaemonEventsConsumer()
		r.QueuedDelivery = g.QueuedDelivery()
		r.WorktreeSweeper = g.WorktreeSweeper()
		r.ScheduleSync = g.TriggerScheduleSync()
		r.TriggerReconciler = g.TriggerReconciler()
		r.TriggerRedriver = g.TriggerRedriver()
		r.Listener = g.APIListener()
	})
	if err != nil {
		return nil, err
	}
	return r, nil
}

// RunAPI builds the api root and supervises what it built until
// ctx ends or a node fails: every node that reports Ready joins g.Probes'
// /readyz, and g.Probes' Drainer is the stop policy's readiness gate and
// budget unless policy names one.
// No node the root reaches serves g.Probes, so a probe listener on the server
// address does: started before every node, stopped after them.
func (g *Graph) RunAPI(ctx context.Context, policy lifecyclekit.Policy) error {
	if _, err := g.BuildAPI(); err != nil {
		return err
	}
	probes, err := g.probeListener()
	if err != nil {
		return fmt.Errorf("build api: %w", err)
	}
	return g.b.Supervise(ctx, policy, g.Probes, probes...)
}

